def seed_existing_assignments(apps, schema_editor):
    User = apps.get_model('django_layuix_rbac', 'UserProfile')
    Assignment = apps.get_model('django_layuix_rbac', 'PositionAssignment')
    rows = []
    today = django.utils.timezone.localdate()
    users = User.objects.filter(positions__isnull=False).distinct().prefetch_related('positions')
    for user in users:
        for position in user.positions.all():
            rows.append(Assignment(
                user_id=user.pk,
                position_id=position.pk,
                position_name=position.name,
                is_primary=bool(user.position_id == position.pk),
                start_date=today,
                change_reason='历史岗位迁移',
            ))
    if rows:
        Assignment.objects.bulk_create(rows, batch_size=500)


def clear_assignments(apps, schema_editor):
    Assignment = apps.get_model('django_layuix_rbac', 'PositionAssignment')
    Assignment.objects.all().delete()


